def ln_of(p):
    ln = LINE.get(p['id'], 'gbt')
    if p['id'] in PHEV_IDS: ln = ln + ' phev'
    return ln

def bundle_for(m):
    if str(m.get('type')) == 'PHEV': return BUNDLES[2]
    return BUNDLES[0] if 'GB/T' in str(m.get('ac', '')) else BUNDLES[1]

