SKU_IMG_FILES = {1: '/assets/sku/adapter-premium.png', 8: '/assets/sku/adapter-base.png', 2: '/assets/sku/adapter-reverse.png', 6: '/assets/sku/adapter-dc-ccs2.png', 25: '/assets/sku/adapter-t1t2.png', 3: '/assets/sku/cable-t2gbt-5m.png', 4: '/assets/sku/cable-t2gbt-7m.png', 9: '/assets/sku/cable-t2gbt-1ph.png', 15: '/assets/sku/cable-t2gbt-10m.png', 5: '/assets/sku/portable-gbt7.png', 19: '/assets/sku/portable-type2.png', 20: '/assets/sku/portable-type2.png', 11: '/assets/sku/v2l-adapter.png', 12: '/assets/sku/holder-gbt.png', 17: '/assets/sku/smazka-silicone.png', 13: '/assets/sku/station-gbt7.png', 16: '/assets/sku/station-2in1.png', 23: '/assets/sku/station-t2-7kw.png', 24: '/assets/sku/station-t2-22kw.png', 21: '/assets/sku/cable-t2t2-5m.png', 22: '/assets/sku/cable-t2t2-7m.png', 26: '/assets/sku/cable-t2t2-5m.png', 14: '/assets/sku/udlinitel-gbt.png'}

def art_for(p):
    f = SKU_IMG_FILES.get(p['id'])
    if f:
        return '<img src="' + f + '" alt="' + html.escape(p['name']) + '" loading="lazy" decoding="async">'
    return SKU_ART.get(p['cat'], SKU_ART['Аксессуары'])

def shop_card_html(p, badge=None):
    tag = TAGS.get(p['id'])
    sp = SPECS.get(p['id'], [])
    spec1 = (html.escape(str(sp[0][0])) + ': ' + html.escape(str(sp[0][1]))) if sp else ''
    bd = ('<span class="pc-tag pc-need">' + BADGE_TXT[badge] + '</span>' if badge else '')
    hit = ('<span class="pc-hit">' + tag + '</span>' if tag else '')
    return ('<div class="pc-card" data-cat="' + p['cat'] + '" data-ln="' + ln_of(p) + '" data-price="' + str(p['price']) + '">'
      '<a class="pc-media" href="/catalog/' + p['slug'] + '.html" aria-label="' + html.escape(p['name']) + '">' + art_for(p) + hit + bd + '</a>'
      '<div class="pc-body"><span class="pc-cat">' + html.escape(p['cat']) + '</span>'
      '<a class="pc-name" href="/catalog/' + p['slug'] + '.html">' + html.escape(p['name']) + '</a>'
      '<div class="pc-spec-line"><span>' + spec1 + '</span></div>'
      '<div class="pc-bottom"><span class="pc-price">' + fmt_price(p['price']) + '</span>'
      '<span class="pc-btn sku-add pc-add" onclick="ofAdd(' + str(p['id']) + ',this)">В заявку</span></div>'
      '<span class="pc-seller">Оплата — дилеру при получении</span></div></div>')
def catalog_block_for(m, pname):
    skus = MODEL_SKU.get(m['brand'] + '|' + m['model'], [])
    if not skus:
        return ''
    cards = bundle_card_html(bundle_for(m)) + ''.join(shop_card_html(PIDX[i['id']], i['badge']) for i in skus)
    mline = 'gbt' if ('GB/T' in str(m.get('dc', '')) or 'GB/T' in str(m.get('ac', ''))) else 'eu'
    qmodel = html.escape(pname).replace(' ', '%20').replace('&', '%26')
    return ('<h2>Что докупить для ' + html.escape(pname) + '</h2><p class="note">Подбор — по разъёмам этой модели. Комплект дешевле позиций по отдельности. Весь каталог: <a href="/catalog/index.html?line=' + mline + '&model=' + qmodel + '">аксессуары для ' + html.escape(pname) + '</a>.</p><div class="pc-grid">' + cards + '</div>' + order_form_html(pname))

def faq_html(p):
    qs = FAQS.get(p['cat'], []) + [['Как оформляется заявка','Отправляете заявку с телефоном — подтверждаем наличие и доставку в ваш город через ближайший салон-дилера. Оплата — при получении, без предоплаты.']]
    items = ''.join('<div class="faq-q"><b>' + q + '</b><p>' + a + '</p></div>' for q, a in qs)
    ld = json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q, a in qs]}, ensure_ascii=False)
    return '<h2>Частые вопросы</h2><div class="lcard">' + items + '</div><script type="application/ld+json">' + ld + '</script>'

def product_ld(p, url):
    return json.dumps({'@context':'https://schema.org','@type':'Product','name':p['name'],'description':p['descLong'][:300],'brand':{'@type':'Brand','name':'Запас хода'},'offers':{'@type':'Offer','price':str(p['price']),'priceCurrency':'RUB','availability':'https://schema.org/InStock','url':SITE + url}}, ensure_ascii=False)

def cat_intro(p):
    return CATEXT.get(p['cat'], '')

def fits_for(p, limit=12):
    fits = [mm for mm in MODELS if any(i['id'] == p['id'] for i in MODEL_SKU.get(mm['brand'] + '|' + mm['model'], []))]
    fits.sort(key=lambda x: 0 if x['freq']=='Массовый' else 1)
    return ''.join('<a class="fchip" href="/models/' + slug(mm['brand']) + '-' + slug(mm['model']) + '.html">' + html.escape(mm['brand'] + ' ' + mm['model']) + '</a>' for mm in fits[:limit])
PRESELECT_JS = ("<script>(function(){"
  "var q=new URLSearchParams(location.search),model=q.get('model'),line=q.get('line'),cat=q.get('cat');"
  "if(model){var b=document.createElement('div');b.className='pc-model-banner';"
  "b.textContent='Аксессуары для: ';var sb=document.createElement('b');sb.textContent=model;b.appendChild(sb);"
  "var x=document.createElement('button');x.setAttribute('aria-label','Сбросить');x.textContent='\\u2715';"
  "x.addEventListener('click',function(){location.replace('/catalog/')});b.appendChild(x);"
  "var fr=document.getElementById('pc-filters');fr&&fr.parentNode.insertBefore(b,fr);}"
  "if(line&&line!=='all'){[].forEach.call(document.querySelectorAll('#ln-filters .chip'),function(c){if(c.getAttribute('data-ln')===line)ofLineFilter(c);});}"
  "if(cat){[].forEach.call(document.querySelectorAll('#pc-filters .chip'),function(c){if(c.getAttribute('data-cat')===cat)ofFilter(c);});}"
  "function upd(){var vis=0;[].forEach.call(document.querySelectorAll('.pc-card'),function(c){if(c.style.display!=='none')vis++;});"
  "var e=document.getElementById('pc-count');if(e)e.textContent='Найдено: '+vis;}"
  "upd();var g=document.querySelector('.pc-grid');"
  "if(g&&window.MutationObserver)new MutationObserver(upd).observe(g,{attributes:true,attributeFilter:['style']});"
  "var sel=document.getElementById('pc-sort');if(sel)sel.addEventListener('change',function(){"
  "var g2=document.querySelector('.pc-grid');if(!g2)return;var cards=[].slice.call(g2.children),v=sel.value;"
  "if(v==='asc')cards.sort(function(a,b){return (+a.getAttribute('data-price')||0)-(+b.getAttribute('data-price')||0);});"
  "else if(v==='desc')cards.sort(function(a,b){return (+b.getAttribute('data-price')||0)-(+a.getAttribute('data-price')||0);});"
  "cards.forEach(function(c){g2.appendChild(c);});});"
  "})();</script>")


def catalog_build(outdir):
    os.makedirs(os.path.join(outdir,'catalog'), exist_ok=True)
    order = ['Адаптеры','Кабели','Зарядки','Станции','V2L','Аксессуары']
    sorted_p = []
    for cat in order:
        sorted_p += [p for p in PRODUCTS if p['cat'] == cat]
    cats = ''.join('<span class="chip" data-cat="' + c + '" onclick="ofFilter(this)">' + c + '</span>' for c in order)
    grid = ''.join(shop_card_html(p) for p in sorted_p)
    hero = ('<div class="fc-hero" style="margin-top:18px;padding:38px 36px">'
      '<span class="fc-hero-badge">Каталог · 26 позиций · оплата дилеру при получении</span>'
      '<h1 style="color:#fff;margin:14px 0 10px;font-size:clamp(26px,3.6vw,38px);font-weight:800;letter-spacing:-.02em">Каталог аксессуаров для зарядки</h1>'
      '<p style="color:rgba(255,255,255,.88);max-width:640px;margin:0 0 20px;font-size:16px;line-height:1.55">Адаптеры, кабели и зарядки для GB/T- и европейских электромобилей. Заявка за минуту, оплата — дилеру при получении.</p>'
      '<div style="display:flex;gap:10px;flex-wrap:wrap">'
      '<a class="btn" style="background:#fff;color:#001e2b;font-weight:700" href="/quiz/">Подбор за 30 секунд</a>'
      '<a class="btn" style="border:1px solid rgba(255,255,255,.5);color:#fff" href="/b2b/">Дилерам — прайс</a></div></div>'
      '<div class="shop-filters" id="pc-filters"><span class="chip on" data-cat="all" onclick="ofFilter(this)">Все</span>' + cats + '</div><div class="shop-filters" id="ln-filters"><span class="chip on" data-ln="all" onclick="ofLineFilter(this)">Все машины</span><span class="chip" data-ln="gbt" onclick="ofLineFilter(this)">GB/T (Китай)</span><span class="chip" data-ln="eu" onclick="ofLineFilter(this)">Type 2 / CCS2 (Европа)</span><span class="chip" data-ln="phev" onclick="ofLineFilter(this)">Для гибридов (PHEV)</span></div>'
      '<div class="pc-toolbar"><span id="pc-count"></span><label class="pc-sort">Сортировка: <select id="pc-sort"><option value="default">По подбору</option><option value="asc">Сначала дешевле</option><option value="desc">Сначала дороже</option></select></label></div>')

    phev_links = ''.join('<a class="fchip" href="/models/'+s+'.html">'+t+'</a>' for s,t in [
        ('geely-ex5-monjaro-hi-p-phev','Geely Monjaro Hi-P'),
        ('byd-song-plus-dm-i-sealion-05','BYD Song Plus DM-i'),
        ('chery-tiggo-7-8-9-c-dm-phev','Chery Tiggo C-DM'),
        ('jaecoo-7-phev','Jaecoo 7 PHEV'),
        ('haval-h6-phev','Haval H6 PHEV'),
        ('tank-500-hi4-t','Tank 500 Hi4-T'),
        ('jetour-t1-t2-phev','Jetour T1 / T2'),
        ('mitsubishi-outlander-phev-jp-eu','Outlander PHEV')])
    phev_block = ('<h2 style="margin-top:34px">Подборка для гибридов (PHEV)</h2>'
      '<p class="note">Для гибрида хватает домашней зарядки 3,5–7,4 кВт, адаптер нужен только если у вашей версии разъём GB/T. <a href="/blog/phev-rossiya-2026.html">Гид по PHEV 2026 →</a></p>'
      '<div class="fsec">' + phev_links + '</div>')
    body = hero + '<div class="pc-grid">' + grid + '</div>' + phev_block + order_form_html('Каталог аксессуаров') + PRESELECT_JS
    WRITE_PAGE(os.path.join(outdir,'catalog','index.html'), 'Каталог аксессуаров для зарядки электромобилей — адаптеры, кабели, зарядки | Запас хода', 'Каталог аксессуаров для зарядки электромобилей в России: адаптеры Type 2 → GB/T, DC-адаптеры CCS2 → GB/T, кабели, портативные зарядки, станции. Подбор под модель, оплата дилеру при получении.', body, '/catalog/index.html', crumbs=[('', 'Каталог')])
    for p in PRODUCTS:
        url = '/catalog/' + p['slug'] + '.html'
        tag = TAGS.get(p['id'])
        spec_rows = ''.join('<tr><td>' + html.escape(str(k)) + '</td><td>' + html.escape(str(v)) + '</td></tr>' for k, v in SPECS.get(p['id'], []))
        if p.get('note'):
            spec_rows += '<tr><td>Важно знать</td><td>' + html.escape(p['note']) + '</td></tr>'
        rel = [x for x in PRODUCTS if x['cat'] == p['cat'] and x['id'] != p['id']][:4]
        rel_html = ('<h2>Похожие товары</h2><div class="pc-grid">' + ''.join(shop_card_html(x) for x in rel) + '</div>') if rel else ''
        fh = fits_for(p)
        hit_b = ('<span class="pc-hit pz-hit">' + tag + '</span>' if tag else '')
        body = ('<div class="pz-hero">'
          '<div class="pz-gallery">' + art_for(p) + '</div>'
          '<div class="pz-buy">'
          '<div class="pz-badges">' + hit_b + '<span class="fbadge">Продавец: «Запас хода»</span></div>'
          '<h1>' + html.escape(p['name']) + '</h1>'
          '<div class="pz-price">' + fmt_price(p['price']) + '</div>'
          '<div class="ctas pz-ctas"><span class="btn lime pz-btn sku-add" onclick="ofAdd(' + str(p['id']) + ',this)">В заявку</span></div>'
          '<div class="pz-delivery">Оплата — дилеру при получении. Заявка ни к чему не обязывает: подтвердим наличие и свяжемся с вами.</div>'
          '<div class="pz-perks"><span><b>Доставка</b> в ваш город через салон-дилера</span>'
          '<span>Проверка при получении</span>'
          '<span>Консультация по разъёмам — бесплатно</span></div>'
          '<a class="pz-ask" href="/forum/">Задать вопрос о товаре на форуме →</a>'
          '</div></div>'
          '<div class="pz-sec"><h2>Характеристики</h2><table class="spec-table">' + spec_rows + '</table></div>'
          '<div class="pz-sec"><h2>О товаре</h2><p>' + html.escape(p['descLong']) + '</p><p class="note">' + cat_intro(p) + '</p></div>'
          + (('<div class="pz-sec"><h2>Подходит для</h2><p class="note">Разъёмы и подбор — на страницах моделей:</p><div class="pz-fits">' + fh + '</div></div>') if fh else '')
          + faq_html(p)
          + rel_html
          + order_form_html(p['name'])
          + '<script type="application/ld+json">' + product_ld(p, url) + '</script>')
        WRITE_PAGE(os.path.join(outdir,'catalog', p['slug'] + '.html'), p['name'] + ' — заказать | Запас хода', (p['name'] + ': ' + p['desc'] + ' Подбор под модель, оплата дилеру при получении.')[:300], body, url, crumbs=[('/catalog/index.html','Каталог'),('',p['name'])])

def of_filter_js():
    return '<script>function ofFilter(el){document.querySelectorAll(\'#pc-filters .chip\').forEach(function(c){c.classList.remove(\'on\')});el.classList.add(\'on\');var cat=el.getAttribute(\'data-cat\');document.querySelectorAll(\'.pc-grid .pc-card\').forEach(function(card){card.style.display=(cat===\'all\'||card.getAttribute(\'data-cat\')===cat)?\'\':\'none\'})}</script>' + '<script>function ofLineFilter(el){document.querySelectorAll("#ln-filters .chip").forEach(function(c){c.classList.remove("on")});el.classList.add("on");var ln=el.getAttribute("data-ln");document.querySelectorAll(".pc-grid .pc-card").forEach(function(card){var L=(card.getAttribute("data-ln")||"all").split(" ");card.style.display=(ln==="all"||L.indexOf(ln)>=0)?"":"none"})}</script>'

ORDER_JS = '<script>\nvar OF_GAS=\'https://script.google.com/macros/s/AKfycby_Zx4ahWRuCX2Jq--yf6FqVpAOBqb9bEvj0rbGPJyFIr45WPcuZ4EKci-n-B2d3VzKQw/exec\';\nfunction ofCart(){try{return JSON.parse(sessionStorage.getItem(\'of_items\')||\'[]\')}catch(e){return[]}}\nfunction ofSave(c){try{sessionStorage.setItem(\'of_items\',JSON.stringify(c))}catch(e){}ofRender()}\nfunction ofAdd(id,b){var ps=window.OF_PRODUCTS||[];var p=null;for(var i=0;i<ps.length;i++)if(ps[i].id===id)p=ps[i];if(!p)return;var c=ofCart(),f=null;for(var j=0;j<c.length;j++)if(c[j].id===id)f=c[j];if(f)f.qty++;else c.push({id:p.id,name:p.name,qty:1,price:p.price,emoji:p.emoji});ofSave(c);if(b){b.textContent=\'Добавлено ✓\';setTimeout(function(){b.textContent=\'В заявку\'},1400)}}\nfunction ofAddB(id,b){var ps=window.OF_BUNDLES||[];var p=null;for(var i=0;i<ps.length;i++)if(ps[i].id===id)p=ps[i];if(!p)return;var c=ofCart();var f=null;for(var j=0;j<c.length;j++)if(c[j].id===id)f=c[j];if(!f)c.push({id:p.id,name:p.name,qty:1,price:p.price,emoji:p.emoji});ofSave(c);if(b){b.textContent=\'В заявке ✓\';setTimeout(function(){b.textContent=\'В заявку\'},1400)}}\nfunction ofQty(id,d){var c=ofCart();for(var j=0;j<c.length;j++){if(c[j].id===id){c[j].qty+=d;if(c[j].qty<1)c.splice(j,1);break}}ofSave(c)}\nfunction ofDel(id){ofSave(ofCart().filter(function(x){return x.id!==id}))}\nfunction ofRender(){var el=document.getElementById(\'of-items\');if(!el)return;var c=ofCart();if(!c.length){el.innerHTML=\'<div class="note">Корзина пуста — выберите позиции из каталога выше.</div>\'}else{var tot=0,h=\'\';for(var i=0;i<c.length;i++){var x=c[i];var s=x.price*x.qty;tot+=s;h+=\'<div class="of-item"><span>\'+ (x.emoji?x.emoji+\' \':\'\') +x.name+\'</span><span class="of-qty"><button type="button" onclick="ofQty(\'+x.id+\',-1)" aria-label="минус">−</button><span>\'+x.qty+\'</span><button type="button" onclick="ofQty(\'+x.id+\',1)" aria-label="плюс">+</button></span><span>\'+s.toLocaleString(\'ru-RU\')+\' \\u20bd</span></div>\'}h+=\'<div class="of-total">Итого: \'+tot.toLocaleString(\'ru-RU\')+\' \\u20bd</div>\';el.innerHTML=h}ofBar()}\nfunction ofBar(){var bar=document.getElementById(\'pc-bar\');if(!bar)return;var c=ofCart();if(!c.length){bar.style.display=\'none\';return}var tot=0,n=0;for(var i=0;i<c.length;i++){tot+=c[i].price*c[i].qty;n+=c[i].qty}bar.style.display=\'block\';document.getElementById(\'pc-bar-txt\').textContent=\'В заявке: \'+n+\' поз. · \'+tot.toLocaleString(\'ru-RU\')+\' \\u20bd\'}\nfunction ofSubmit(e){e.preventDefault();var c=ofCart();var st=document.getElementById(\'of-status\');var f=e.target;var d={t:\'site_order\',model:(window.OF_MODEL||\'\'),items:c,total:c.reduce(function(s,x){return s+x.price*x.qty},0),name:f.name.value,phone:f.phone.value,city:f.city.value,comment:f.comment.value};st.innerHTML=\'<p class="note">Отправляем…</p>\';fetch(OF_GAS,{method:\'POST\',headers:{\'Content-Type\':\'text/plain;charset=utf-8\'},body:JSON.stringify(d)}).then(function(r){return r.json()}).then(function(){if(window.ym&&window.YM_ID){try{ym(window.YM_ID,\'reachGoal\',\'order_form\')}catch(e){}}st.innerHTML=\'<div class="of-ok">✓ Заявка отправлена! Свяжемся с вами по телефону или в Telegram. Оплата — дилеру при получении.</div>\';f.reset();ofSave([])}).catch(function(){st.innerHTML=\'<p class="note">Не удалось отправить — напишите нам в Telegram: @zapashoda_ev.</p>\'})}\ndocument.addEventListener(\'DOMContentLoaded\',function(){var f=document.getElementById(\'order-form\');if(f){f.addEventListener(\'submit\',ofSubmit);ofRender()}});\n</script>' + of_filter_js()
